create table public.rental_bulk_operation_receipts(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operation_key text not null,request_key text not null,requested_by uuid not null references auth.users(id),result jsonb not null,created_at timestamptz not null default now(),unique(organisation_id,request_key));
create index rental_bulk_operation_receipts_org_created_idx on public.rental_bulk_operation_receipts(organisation_id,created_at desc);create index rental_bulk_operation_receipts_requested_by_idx on public.rental_bulk_operation_receipts(requested_by);alter table public.rental_bulk_operation_receipts enable row level security;create policy "rental_bulk_receipts_manager_read" on public.rental_bulk_operation_receipts for select to authenticated using(public.rental_financial_manager_authorized(organisation_id));
create or replace function public.rental_bulk_update_vacancy_status(p_org uuid,p_vacancy_ids uuid[],p_status text,p_request_key text)returns jsonb language plpgsql security definer set search_path='' as $$ declare v_result jsonb:='[]'::jsonb;v_existing jsonb;v_id uuid;v_count int:=0;begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org) or p_status not in('draft','preparing','marketing','applications_open','paused','withdrawn') or cardinality(p_vacancy_ids) is null or cardinality(p_vacancy_ids)>100 or length(btrim(coalesce(p_request_key,'')))<8 then raise exception 'Invalid bulk command';end if;select result into v_existing from public.rental_bulk_operation_receipts where organisation_id=p_org and request_key=p_request_key;if found then return v_existing;end if;foreach v_id in array p_vacancy_ids loop begin if exists(select 1 from public.rental_vacancies v join public.rental_properties p on p.id=v.property_id where v.id=v_id and v.organisation_id=p_org and public.rental_branch_access(p.organisation_id,p.branch_id)) then update public.rental_vacancies set status=p_status,updated_at=now() where id=v_id;v_result:=v_result||jsonb_build_array(jsonb_build_object('id',v_id,'status','updated'));v_count:=v_count+1;else v_result:=v_result||jsonb_build_array(jsonb_build_object('id',v_id,'status','denied_or_missing'));end if;exception when others then v_result:=v_result||jsonb_build_array(jsonb_build_object('id',v_id,'status','failed'));end;end loop;v_result:=jsonb_build_object('operation','vacancy_status','updated_count',v_count,'results',v_result);insert into public.rental_bulk_operation_receipts(organisation_id,operation_key,request_key,requested_by,result)values(p_org,'vacancy_status',p_request_key,auth.uid(),v_result);return v_result;end $$;
revoke all on function public.rental_bulk_update_vacancy_status(uuid,uuid[],text,text)from public,anon;grant execute on function public.rental_bulk_update_vacancy_status(uuid,uuid[],text,text)to authenticated;
